<script lang="ts">
	import { getContext, type Snippet } from "svelte";
	import Label from "./Label.svelte";
	import FieldError from "./FieldError.svelte";
	import type { FormField, FormIssue } from "./types.js";
	import StringOrSnippet from "../util/StringOrSnippet.svelte";

    /**
     * @description
     * Internal wrapper used by Input, Select and Textarea to render the label, field
     * border, prefix/suffix decorations, help text and error messages in a consistent layout.
     *
     * @cssprop --field-background -- Background color of the field container.
     * @cssprop --field-border-size -- Border width of the field container.
     * @cssprop --field-border-style -- Border style of the field container.
     * @cssprop --field-border-color -- Border color of the field container.
     * @cssprop --field-border-radius -- Border radius of the field container.
     */
    let {
        id,
        contained,
        prefix,
        suffix,
        label,
        labelTip,
        labelHelp,
        help,
        type = "text",
        direction = 'column', // 'row' | 'column'
        scale = 'md',
        required,
        children,
        field,
        issue,
    }: {
        id: string;
        contained?: boolean;
        prefix?: string | Snippet;
        suffix?: string | Snippet;
        help?: string | Snippet;
        type?: string;
        label?: string | Snippet;
        labelTip?: string | Snippet;
        labelHelp?: string | Snippet;
        direction?: 'row' | 'column';
        /** Size variant controlling font-size. Em-based tokens cascade automatically. */
        scale?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
        required?: boolean;
        children: Snippet;
        field?: FormField;
        issue?: FormIssue;
    } = $props();

    if(contained === undefined) { contained = getContext('lutra.form.contained') ?? getContext('lutra.contained') ?? false; }
</script>

{#snippet _prefix()}
    <div class="Fix Prefix">
        <StringOrSnippet content={prefix} />
    </div>
{/snippet}

{#snippet _suffix()}
    <div class="Fix Suffix">
        <StringOrSnippet content={suffix} />
    </div>
{/snippet}

<div class="FieldContentContainer {scale}">
    <div class="FieldContent {type} {direction}" class:contained>
        <Label {label} tip={labelTip} help={labelHelp} {id} {required} />
        {#if contained}
            <div
                class="Field"
                
                class:invalid={field?.tainted && issue?.code}
            >
                {#if prefix}
                    {@render _prefix()}
                {/if}
    
                {@render children()}
    
                {#if suffix}
                    {@render _suffix()}
                {/if}
            </div>
        {:else}
            {#if prefix}
                {@render _prefix()}
            {/if}
    
            {@render children()}
    
            {#if suffix}
                {@render _suffix()}
            {/if}
        {/if}
    
    </div>
    
    {#if help}
        <div class="Help">
            <StringOrSnippet content={help} />
        </div>
    {/if}
    
    {#if field?.tainted && issue?.code}
        <FieldError code={issue.code} message={issue.message} />
    {/if}
</div>

<style>
    .FieldContentContainer {
        display: flex;
        flex-direction: column;
        gap: var(--form-field-inside-gap);
        min-width: 0;
    }
    .FieldContent {
        display: flex;
        gap: var(--form-label-gap, var(--space-xs));
        flex-direction: column;
        font-size: 1em;
        min-width: 0;
    }
    .FieldContent.row {
        flex-direction: row-reverse;
        justify-content: start;
        align-items: center;
        flex-shrink: 0;
    }
    .Field {
        background: var(--field-background, transparent);
        border: var(--field-border-size) var(--field-border-style) var(--field-border-color);
        border-radius: var(--field-border-radius);
        display: flex;
        min-width: 0;
    }
    .Field.invalid {
        border-color: var(--field-border-color-invalid);
    }
    .Field > *:not(input) {
        flex-grow: 0;
        flex-shrink: 0;
    }
    .Fix {
        display: flex;
        align-items: center;
        padding-inline: var(--form-field-gap, var(--space-md));
        font-size: 1em;
        text-box: trim-both cap alphabetic;
        color: var(--text-color-p-subtle);
    }
    .Suffix {
        padding-inline-start: 0;
    }
    .Prefix {
        padding-inline-end: 0;
    }
    .Field:has(:global(input:focus-visible)),
    .Field:has(:global(select:focus-visible)),
    .Field:has(:global(textarea:focus-visible)) {
        outline: var(--focus-ring);
        border-color: var(--focus-ring-color);
    }
    .Field:has(:global(input:focus-visible:user-invalid)),
    .Field:has(:global(select:focus-visible:user-invalid)),
    .Field:has(:global(textarea:focus-visible:user-invalid)) {
        outline-color: var(--focus-ring-color-invalid); 
        border-color: var(--focus-ring-color-invalid);
    }
    .Field:has(.Prefix) :global(input) {
        padding-inline-start: var(--space-xxs);
    }
    .Field :global(button) {
        margin-inline-end: var(--space-xxs);
    }
    .Field :global(button:focus-visible) {
        outline: var(--focus-ring);
        outline-offset: 3px;
        border-radius: calc(var(--field-border-radius) - 2px);
    }
    .Help {
        font-size: var(--font-size-sm);
        line-height: var(--font-line-height-tight);
        color: var(--text-color-p-subtle);
        font-weight: var(--font-weight-light);
    }

    .FieldContentContainer.xs { font-size: var(--font-size-xs); }
    .FieldContentContainer.sm { font-size: var(--font-size-sm); }
    .FieldContentContainer.lg { font-size: var(--font-size-h5); }
    .FieldContentContainer.xl { font-size: var(--font-size-h4); }
</style>